# ❌ 错误：信号已断开后继续使用
func _ready() -> void:
    some_signal.connect(_on_signal)

func _exit_tree() -> void:
    some_signal.disconnect(_on_signal)  # 忘记断开

# ✅ 正确：使用 Callable 管理连接
var _signal_callable: Callable

func _ready() -> void:
    _signal_callable = _on_signal
    some_signal.connect(_signal_callable)

func _exit_tree() -> void:
    if some_signal.is_connected(_signal_callable):
        some_signal.disconnect(_signal_callable)
